    void notify();
};
struct Parent : std::enable_shared_from_this<Parent> {
    std::vector<std::shared_ptr<Child>> kids;  // owning
    void onEvent() { /* ... */ }
    void addChild() {   // only after Parent is owned by a shared_ptr
        auto c = std::make_shared<Child>();
        c->parent = weak_from_this();
        kids.push_back(std::move(c));
    }
};
void Child::notify() {
    if (auto p = parent.lock())   // null if Parent is gone
        p->onEvent();
}

