#include <cstdint>
#include <cstdlib>

void* aligned_malloc(size_t size, size_t align) {
    if (align == 0 || (align & (align - 1)) != 0) return nullptr;   // power of two only
    if (size > SIZE_MAX - align - sizeof(void*)) return nullptr;     // size overflow
    // Room for: the payload, worst-case padding, and the original pointer.
    void* raw = std::malloc(size + align - 1 + sizeof(void*));
    if (!raw) return nullptr;
    uintptr_t start = reinterpret_cast<uintptr_t>(raw) + sizeof(void*);
    uintptr_t aligned = (start + align - 1) & ~static_cast<uintptr_t>(align - 1);
    reinterpret_cast<void**>(aligned)[-1] = raw;    // stash what free() needs
    return reinterpret_cast<void*>(aligned);
}

void aligned_free(void* p) {
    if (p) std::free(static_cast<void**>(p)[-1]);
}

